 package approval

-import "time"
+import (
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/base64"
+	"errors"
+	"fmt"
+	"strconv"
+	"strings"
+	"time"
+)

+// Sign creates a token that certifies actor approved taskID, valid until expires.
 func Sign(secret []byte, taskID, actor string, expires time.Time) (string, error) {
-	return "", nil
+	if len(secret) < 32 {
+		return "", errors.New("approval: secret must be at least 32 bytes")
+	}
+	if taskID == "" {
+		return "", errors.New("approval: taskID must not be empty")
+	}
+	if actor == "" {
+		return "", errors.New("approval: actor must not be empty")
+	}
+
+	payload := buildPayload(taskID, actor, expires)
+	mac := computeMAC(secret, payload)
+	return payload + "." + base64.RawURLEncoding.EncodeToString(mac), nil
 }

+// Verify checks token against taskID and now, returning the approving actor.
 func Verify(secret []byte, token, taskID string, now time.Time) (string, error) {
-	return "", nil
+	payload, macB64, ok := strings.Cut(token, ".")
+	if !ok {
+		return "", errors.New("approval: malformed token: missing MAC separator")
+	}
+
+	gotMAC, err := base64.RawURLEncoding.DecodeString(macB64)
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token MAC: %w", err)
+	}
+
+	wantMAC := computeMAC(secret, payload)
+	if !hmac.Equal(gotMAC, wantMAC) {
+		return "", errors.New("approval: MAC mismatch")
+	}
+
+	fields := strings.Split(payload, "|")
+	if len(fields) != 3 {
+		return "", errors.New("approval: malformed token payload: expected 3 fields")
+	}
+
+	taskIDBytes, err := base64.RawURLEncoding.DecodeString(fields[0])
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token taskID: %w", err)
+	}
+	actorBytes, err := base64.RawURLEncoding.DecodeString(fields[1])
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token actor: %w", err)
+	}
+	expiresUnix, err := strconv.ParseInt(fields[2], 10, 64)
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token expiry: %w", err)
+	}
+
+	payloadTaskID := string(taskIDBytes)
+	if payloadTaskID != taskID {
+		return "", fmt.Errorf("approval: taskID mismatch: token is for %q, requested %q", payloadTaskID, taskID)
+	}
+
+	expires := time.Unix(expiresUnix, 0).UTC()
+	if !now.UTC().Before(expires) {
+		return "", fmt.Errorf("approval: token expired at %s", expires)
+	}
+
+	return string(actorBytes), nil
+}
+
+// buildPayload encodes taskID and actor individually with base64 so that the
+// "|" delimiter joining fields never collides with characters inside them.
+func buildPayload(taskID, actor string, expires time.Time) string {
+	encTaskID := base64.RawURLEncoding.EncodeToString([]byte(taskID))
+	encActor := base64.RawURLEncoding.EncodeToString([]byte(actor))
+	expiresUnix := strconv.FormatInt(expires.UTC().Unix(), 10)
+	return encTaskID + "|" + encActor + "|" + expiresUnix
+}
+
+func computeMAC(secret []byte, payload string) []byte {
+	mac := hmac.New(sha256.New, secret)
+	mac.Write([]byte(payload))
+	return mac.Sum(nil)
 }
